(() => {
 const stem=document.getElementById('stem');if(!stem)return;
 const histories=new Map();let key='',state,hold,drag=null,suppressClick=false;
 const toolbar=document.createElement('div');toolbar.className='interaction-tools';toolbar.innerHTML='<span>长按题干后拖动勾画 · 长按选项排除</span>';stem.before(toolbar);
 const style=document.createElement('style');style.textContent='.interaction-tools{margin:0 0 16px}.interaction-tools span{font-size:12px;color:#7a8ba6;line-height:1.6}#stem{touch-action:none;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none}#stem [data-ink]{cursor:text}.drawing-enabled{outline:1px dashed #91b3e8;outline-offset:6px}.ink-highlight{background:#ffe99a!important;text-decoration:underline;text-decoration-color:#d6b057}.option{touch-action:pan-y}.option.excluded{background:#f0f2f5!important;color:#8b94a1!important}.option.excluded span{text-decoration:line-through}.option:focus-visible{outline:3px solid #e5a446;outline-offset:3px}';document.head.append(style);
 function signal(type){document.dispatchEvent(new CustomEvent('prototype-interaction',{detail:{type}}));}
 function paint(){stem.querySelectorAll('[data-ink]').forEach(el=>el.classList.toggle('ink-highlight',state.marks.has(Number(el.dataset.ink))));}
 function enhance(){observer.disconnect();const next=(document.getElementById('number')?.textContent||'')+'|'+stem.textContent;if(next!==key){key=next;state=histories.get(key)||{marks:new Set(),excluded:new Set()};histories.set(key,state);}if(!stem.querySelector('[data-ink]')){const walker=document.createTreeWalker(stem,NodeFilter.SHOW_TEXT);const texts=[];while(walker.nextNode())texts.push(walker.currentNode);let index=0;texts.forEach(node=>{const frag=document.createDocumentFragment();for(const ch of node.textContent){const span=document.createElement('span');span.dataset.ink=index++;span.textContent=ch;frag.append(span);}node.replaceWith(frag);});}paint();document.querySelectorAll('.option').forEach((option,index)=>{option.dataset.eliminate=index;option.tabIndex=0;option.classList.toggle('excluded',state.excluded.has(index));option.title='长按排除，再次长按恢复；键盘可按 Delete';});observer.observe(stem,{childList:true,subtree:true});const area=document.getElementById('options')||document.getElementById('answerArea');if(area)observer.observe(area,{childList:true,subtree:true});}
 const observer=new MutationObserver(enhance);enhance();
 function cancelMark(){clearTimeout(hold);drag=null;stem.classList.remove('drawing-enabled');}
 function finish(e){if(drag&&e.pointerId!==drag.pointerId)return;if(drag?.armed){const a=Math.min(drag.start,drag.end),b=Math.max(drag.start,drag.end);const removing=Array.from({length:b-a+1},(_,i)=>a+i).every(i=>state.marks.has(i));for(let i=a;i<=b;i++)removing?state.marks.delete(i):state.marks.add(i);paint();signal('mark');}cancelMark();}
 stem.addEventListener('contextmenu',e=>e.preventDefault());
 stem.addEventListener('pointerdown',e=>{if(e.button!==0||e.isPrimary===false)return;const hit=e.target.closest('[data-ink]');if(!hit)return;cancelMark();const index=Number(hit.dataset.ink);drag={start:index,end:index,armed:false,pointerId:e.pointerId,x:e.clientX,y:e.clientY};stem.setPointerCapture(e.pointerId);hold=setTimeout(()=>{if(drag){drag.armed=true;stem.classList.add('drawing-enabled');}},550);});
 window.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.pointerId)return;if(!drag.armed&&Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>12){cancelMark();return;}if(drag.armed){const hit=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-ink]');if(hit&&stem.contains(hit))drag.end=Number(hit.dataset.ink);}});
 window.addEventListener('pointerup',finish);window.addEventListener('pointercancel',e=>{if(drag?.pointerId===e.pointerId)cancelMark();});
 function eliminate(option){const input=option.querySelector('input');if(!input||input.disabled)return;const index=Number(option.dataset.eliminate);if(state.excluded.has(index))state.excluded.delete(index);else{state.excluded.add(index);if(input.checked){input.checked=false;if(typeof answers!=='undefined'){answers[current]=null;session.answers[current]=null;saveSession();document.getElementById('submitAnswer').disabled=true;renderPanel();}else if(typeof answerState!=='undefined'){answerState[current]=Array.isArray(answerState[current])?answerState[current].filter(i=>i!==index):null;renderProgress();}else if(typeof selected!=='undefined'){selected=null;document.getElementById('confirmAnswer').disabled=true;}}}option.classList.toggle('excluded',state.excluded.has(index));signal('exclude');}
 let optionHold=null;
 document.addEventListener('pointerdown',e=>{const option=e.target.closest('.option');if(!option||e.button!==0)return;suppressClick=false;optionHold={x:e.clientX,y:e.clientY,timer:setTimeout(()=>{suppressClick=true;eliminate(option);optionHold=null;},550)};});
 document.addEventListener('pointermove',e=>{if(optionHold&&Math.hypot(e.clientX-optionHold.x,e.clientY-optionHold.y)>10){clearTimeout(optionHold.timer);optionHold=null;}});
 for(const event of ['pointerup','pointercancel'])document.addEventListener(event,()=>{if(optionHold)clearTimeout(optionHold.timer);optionHold=null;});
 document.addEventListener('click',e=>{const option=e.target.closest('.option');if(option&&(suppressClick||option.classList.contains('excluded'))){e.preventDefault();e.stopImmediatePropagation();suppressClick=false;}},true);
 document.addEventListener('contextmenu',e=>{if(e.target.closest('.option'))e.preventDefault();});
 document.addEventListener('keydown',e=>{const option=e.target.closest('.option');if(option&&['Delete','Backspace'].includes(e.key)){e.preventDefault();eliminate(option);}});
 window.addEventListener('blur',()=>{cancelMark();if(optionHold)clearTimeout(optionHold.timer);optionHold=null;});
})();
